import{_ as t,c as p,a2 as h,o as r}from"./chunks/framework.CqbvlPrP.js";const j=JSON.parse('{"title":"第三章 世间有谁可以不衰老和死亡？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/3第三章 世间有谁可以不衰老和死亡.md","filePath":"meditation/巴利文大藏经/3第三章 世间有谁可以不衰老和死亡.md"}'),e={name:"meditation/巴利文大藏经/3第三章 世间有谁可以不衰老和死亡.md"};function i(n,a,o,m,s,d){return r(),p("div",null,a[0]||(a[0]=[h('<h1 id="第三章-世间有谁可以不衰老和死亡" tabindex="-1">第三章 世间有谁可以不衰老和死亡？ <a class="header-anchor" href="#第三章-世间有谁可以不衰老和死亡" aria-label="Permalink to &quot;第三章 世间有谁可以不衰老和死亡？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应3经/老死经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王对佛陀说：“世尊，已经出生在世间的人或者有生命的众生，有哪一个是可以永远不衰老、永远不死的呢？有那种出生在世间可以免除衰老和死亡的人或者众生吗？”</p><p>佛陀说：“大王，只要出生在世间，任何的人或者众生都无法免除衰老和死亡，有出生就会有衰老和死亡。即使是那些高贵权威的王族，他们有无数的财物，有无数的金银珠宝，有无上的权利，有无数的土地粮食，有无数的宫殿楼阁，有无数的军队、仆人……他们还是要衰老和死亡的。更何况是那些德高望重的长老，功勋卓著的将帅，富甲天下的富翁，他们也是要衰老和死亡的，一般的平头百姓当然也无法避免衰老和死亡。</p><p>大王，甚至于那些在世间修行，烦恼已经除尽，修行已经圆满，在世间应该做的事情已经做好，所有的挂念和负担已经放下，已经证悟解脱果位，不会再被世间任何的事物事情束缚捆绑，依靠如来的正法修行已经完全究竟解脱的如来弟子们，对于他们来说，他们在世间的这个身体也如同陶瓷器那样的脆弱，他们要除灭对这个世间脆弱身体的挂念和执着才可以真正解脱出生死的轮回，有生就有死，无生就无死，出生世间没有谁可以免除衰老和死亡，只有不生才能不死。</p><p>大王，再华丽漂亮的马车也会老旧破损，再强壮的身体也会衰老死亡，如来的正法永恒不变，按如来的正法去修行就可以从生死的轮回中解脱出来，要经常的来听闻如来说法，以此除灭烦恼和痛苦，最终证悟解脱的果位，从生死的轮回中永远的解脱出来。”</p><p>这时，佛陀说偈言：</p><p>「王车美亦坏，身体迈向老。</p><p>正法永不老。善人所语善。」</p><p>巴利语原版经文</p><p>SN.3.3/(3) Jarāmaraṇasuttaṃ</p><p>114. Sāvatthinidānaṃ Ekamantaṃ nisinno kho rājā pasenadi kosalo bhagavantaṃ etadavoca– “atthi nu kho, bhante, jātassa aññatra jarāmaraṇā”ti? “Natthi kho, mahārāja, jātassa aññatra jarāmaraṇā. Yepi te, mahārāja, khattiyamahāsālā aḍḍhā mahaddhanā mahābhogā pahūtajātarūparajatā pahūtavittūpakaraṇā pahūtadhanadhaññā, tesampi jātānaṃ natthi aññatra jarāmaraṇā. Yepi te, mahārāja, brāhmaṇamahāsālā …pe… gahapatimahāsālā aḍḍhā mahaddhanā mahābhogā pahūtajātarūparajatā pahūtavittūpakaraṇā pahūtadhanadhaññā, tesampi jātānaṃ natthi aññatra jarāmaraṇā. Yepi te, mahārāja, bhikkhū arahanto khīṇāsavā vusitavanto katakaraṇīyā ohitabhārā anuppattasadatthā parikkhīṇabhavasaṃyojanā sammadaññāvimuttā, tesaṃ pāyaṃ kāyo bhedanadhammo nikkhepanadhammo”ti. Idamavoca …pe…</p><p>“Jīranti ve rājarathā sucittā, atho sarīrampi jaraṃ upeti.</p><p>Satañca dhammo na jaraṃ upeti, santo have sabbhi pavedayantī”ti.</p>',15)]))}const k=t(e,[["render",i]]);export{j as __pageData,k as default};
